import type { SubmittedSignatureSource } from '~/client';

export const submittedSignatureSource: Record<SubmittedSignatureSource, { label: string }> = {
  ui: { label: 'UI by Canvasser' },
  conversation: { label: 'Conversation by Canvasser' },
  'canvasser ballot': { label: 'Petition by Canvasser' },
  'manager ballot': { label: 'Petition by Manager' },
};

export function getSubmittedSignatureSourceLabel(source: SubmittedSignatureSource): string {
  return submittedSignatureSource[source]?.label ?? snakeCaseToCapitalizedCase(source);
}

export const submittedSignatureSources: SelectItem<SubmittedSignatureSource>[] = Object.entries(
  submittedSignatureSource
).map(([value, { label }]) => ({
  value: value as SubmittedSignatureSource,
  name: label,
}));
