import type { SubmittedSignatureStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

export const submittedSignaturesBadge: Record<SubmittedSignatureStatus, { variant: BadgeVariants; label: string }> = {
  valid: { variant: 'success', label: 'Valid' },
  invalid: { variant: 'destructive', label: 'Not Valid' },
  new: { variant: 'info', label: 'New' },
  duplicate: { variant: 'warning', label: 'Duplicate' },
  failed: { variant: 'destructive', label: 'Failed' },
  already_valid: { variant: 'success', label: 'Already Valid' },
  already_invalid: { variant: 'destructive', label: 'Already Invalid' },
};

const defaultSubmittedSignaturesBadge: { variant: BadgeVariants; label: string } = { variant: 'default', label: '' };

export function getSubmittedSignaturesBadge(status: SubmittedSignatureStatus): {
  variant: BadgeVariants;
  label: string;
} {
  return (
    submittedSignaturesBadge[status] ?? {
      ...defaultSubmittedSignaturesBadge,
      label: snakeCaseToCapitalizedCase(status),
    }
  );
}

export const submittedSignatureStatuses: SelectItem<SubmittedSignatureStatus>[] = Object.entries(
  submittedSignaturesBadge
).map(([value, { label }]) => ({
  value: value as SubmittedSignatureStatus,
  name: label,
}));
